-- C09 live read models: one statement snapshot, no new economic balances or write commands.
CREATE SCHEMA workbench;REVOKE ALL ON SCHEMA workbench FROM PUBLIC;GRANT USAGE ON SCHEMA workbench TO htt_app;
INSERT INTO identity.permissions(code,description)VALUES
('workbench.finance.read','Read authorized finance dashboard'),('workbench.sales.read','Read assigned-customer sales dashboard'),('workbench.office.read','Read office operational workbench'),('workbench.customers.read','Read authorized unified customer view'),('workbench.banks.read','Read financial bank hub'),('workbench.warehouse.read','Read quantity-only warehouse workbench');
CREATE FUNCTION identity.seed_workbench_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$
 INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND(
 (r.code IN('ADMIN','FINANCE')AND p.code IN('workbench.finance.read','workbench.banks.read'))OR
 (r.code IN('ADMIN','OFFICE','SALES')AND p.code='workbench.sales.read')OR
 (r.code IN('ADMIN','OFFICE')AND p.code='workbench.office.read')OR
 (r.code IN('ADMIN','OFFICE','SALES','FINANCE')AND p.code='workbench.customers.read')OR
 (r.code IN('ADMIN','WAREHOUSE','OFFICE')AND p.code='workbench.warehouse.read'))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_workbench_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION workbench.unavailable()RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT jsonb_build_object('status','FORBIDDEN','data',NULL)$$;
CREATE FUNCTION workbench.available(p jsonb)RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT jsonb_build_object('status','AVAILABLE','data',p)$$;
CREATE FUNCTION workbench.require_finance()RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('accounting.reports.read');PERFORM crm.require_mobile('accounting.ledger.read');END$$;

-- Same accounting queries as the existing financial report endpoints.
CREATE FUNCTION workbench.profit_loss(p_from date,p_to date)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$

            WITH amounts AS MATERIALIZED(
              SELECT a.id,a.code,a.name,a.kind,a.active,coalesce(sum(l.credit-l.debit)FILTER(WHERE j.posting_date>=p_from AND j.posting_date<p_to),0) AS signed_profit
              FROM accounting.accounts a LEFT JOIN accounting.journal_lines l ON l.company_id=a.company_id AND l.account_id=a.id LEFT JOIN accounting.business_journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id
              WHERE a.company_id=core.current_company() AND a.kind IN('REVENUE','EXPENSE') GROUP BY a.id
            ), totals AS(SELECT coalesce(sum(signed_profit)FILTER(WHERE kind='REVENUE'),0) AS revenue,coalesce(-sum(signed_profit)FILTER(WHERE kind='EXPENSE'),0) AS expenses FROM amounts)
            SELECT jsonb_build_object('companyId',core.current_company(),'currency','AUD','basis','ACCRUAL_GL','snapshotAt',statement_timestamp(),'from',p_from,'to',p_to,
              'totals',jsonb_build_object('revenue',revenue::text,'expenses',expenses::text,'netProfit',(revenue-expenses)::text),
              'items',coalesce((SELECT jsonb_agg(jsonb_build_object('accountId',id,'code',code,'name',name,'kind',kind,'active',active,'amount',(CASE WHEN kind='REVENUE' THEN signed_profit ELSE -signed_profit END)::text)ORDER BY kind DESC,code,id) FROM amounts WHERE false OR signed_profit<>0),'[]'::jsonb)) AS result FROM totals
            
$$;

-- Same accounting queries as the existing financial report endpoints.
CREATE FUNCTION workbench.balance_sheet(p_date date)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$

            WITH year_start AS(SELECT coalesce(NULL::date,(SELECT starts_on FROM accounting.fiscal_years WHERE company_id=core.current_company() AND starts_on<=p_date AND ends_on>p_date ORDER BY starts_on DESC LIMIT 1),make_date(extract(year FROM p_date::date)::int-CASE WHEN extract(month FROM p_date::date)<7 THEN 1 ELSE 0 END,7,1)) AS starts_on), amounts AS MATERIALIZED(
              SELECT a.id,a.code,a.name,a.kind,a.control_kind,a.active,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<=p_date),0) AS signed_balance,
                coalesce(sum(l.credit-l.debit)FILTER(WHERE j.posting_date<(SELECT starts_on FROM year_start)),0) AS prior_profit,
                coalesce(sum(l.credit-l.debit)FILTER(WHERE j.posting_date>=(SELECT starts_on FROM year_start) AND j.posting_date<=p_date),0) AS current_profit
              FROM accounting.accounts a LEFT JOIN accounting.journal_lines l ON l.company_id=a.company_id AND l.account_id=a.id LEFT JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE a.company_id=core.current_company() GROUP BY a.id
            ), totals AS(SELECT coalesce(sum(signed_balance)FILTER(WHERE kind='ASSET'),0) AS assets,coalesce(-sum(signed_balance)FILTER(WHERE kind='LIABILITY'),0) AS liabilities,coalesce(-sum(signed_balance)FILTER(WHERE kind='EQUITY'),0) AS posted_equity,
              coalesce(sum(prior_profit)FILTER(WHERE kind IN('REVENUE','EXPENSE')),0) AS prior_earnings,coalesce(sum(current_profit)FILTER(WHERE kind IN('REVENUE','EXPENSE')),0) AS current_earnings FROM amounts)
            SELECT jsonb_build_object('companyId',core.current_company(),'currency','AUD','basis','ACCRUAL_GL','snapshotAt',statement_timestamp(),'asOf',p_date,'fiscalYearStart',(SELECT starts_on FROM year_start),
              'totals',jsonb_build_object('assets',assets::text,'liabilities',liabilities::text,'postedEquity',posted_equity::text,'priorUnclosedEarnings',prior_earnings::text,'currentYearEarnings',current_earnings::text,'equity',(posted_equity+prior_earnings+current_earnings)::text,'liabilitiesAndEquity',(liabilities+posted_equity+prior_earnings+current_earnings)::text,'difference',(assets-liabilities-posted_equity-prior_earnings-current_earnings)::text),
              'status',CASE WHEN assets=liabilities+posted_equity+prior_earnings+current_earnings THEN 'BALANCED' ELSE 'UNBALANCED' END,
              'items',coalesce((SELECT jsonb_agg(jsonb_build_object('accountId',id,'code',code,'name',name,'kind',kind,'controlKind',control_kind,'active',active,'amount',(CASE WHEN kind='ASSET' THEN signed_balance ELSE -signed_balance END)::text)ORDER BY kind,code,id) FROM amounts WHERE kind IN('ASSET','LIABILITY','EQUITY') AND(false OR signed_balance<>0)),'[]'::jsonb)) AS result FROM totals
            
$$;

-- Same accounting queries as the existing financial report endpoints.
CREATE FUNCTION workbench.aging(p_side text,p_date date,p_party uuid DEFAULT NULL,p_size int DEFAULT 20,p_offset int DEFAULT 0)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$

            WITH documents AS MATERIALIZED(
              SELECT i.company_id,'AR'::text AS side,i.id,i.party_id,i.customer_id AS counterparty_id,i.invoice_date,i.due_on,l.id AS line_id FROM sales.invoices i JOIN sales.invoice_lines l ON l.company_id=i.company_id AND l.invoice_id=i.id WHERE i.company_id=core.current_company() AND p_side='AR'
              UNION ALL
              SELECT b.company_id,'AP',b.id,b.party_id,b.supplier_id,b.invoice_date,b.due_on,l.id FROM purchase.bills b JOIN purchase.bill_lines l ON l.company_id=b.company_id AND l.bill_id=b.id WHERE b.company_id=core.current_company() AND p_side='AP'
            ), movements AS MATERIALIZED(
              SELECT m.item_line_id,sum(m.amount) AS balance FROM accounting.report_open_item_movements m JOIN accounting.report_control_dates d ON d.company_id=m.company_id AND d.source_document_id=m.source_document_id AND d.side=m.side WHERE m.company_id=core.current_company() AND m.side=p_side AND d.posting_date<=p_date GROUP BY m.item_line_id
            ), items AS MATERIALIZED(
              SELECT d.id,d.party_id,d.counterparty_id,d.invoice_date,d.due_on,sum(greatest(m.balance,0)) AS outstanding,sum(greatest(-m.balance,0)) AS credit,sum(m.balance) AS net
              FROM documents d JOIN movements m ON m.item_line_id=d.line_id WHERE(p_party IS NULL OR d.party_id=p_party) GROUP BY d.id,d.party_id,d.counterparty_id,d.invoice_date,d.due_on HAVING bool_or(m.balance<>0)
            ), totals AS(
              SELECT count(*) AS count,coalesce(sum(outstanding)FILTER(WHERE due_on>=p_date),0) AS current,coalesce(sum(outstanding)FILTER(WHERE p_date-due_on BETWEEN 1 AND 30),0) AS d30,coalesce(sum(outstanding)FILTER(WHERE p_date-due_on BETWEEN 31 AND 60),0) AS d60,coalesce(sum(outstanding)FILTER(WHERE p_date-due_on BETWEEN 61 AND 90),0) AS d90,coalesce(sum(outstanding)FILTER(WHERE p_date-due_on>90),0) AS older,coalesce(sum(outstanding),0) AS gross,coalesce(sum(credit),0) AS credits,coalesce(sum(net),0) AS net FROM items
            ), control AS(
              SELECT coalesce(sum(CASE WHEN p_side='AR' THEN l.debit-l.credit ELSE l.credit-l.debit END),0) AS balance FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=core.current_company() AND a.control_kind=p_side AND j.posting_date<=p_date AND(p_party IS NULL OR l.party_id=p_party)
            ), paged AS(SELECT i.*,p.legal_name,d.number FROM items i JOIN crm.parties p ON p.company_id=core.current_company() AND p.id=i.party_id JOIN platform.documents d ON d.company_id=core.current_company() AND d.id=i.id ORDER BY i.due_on,i.id LIMIT p_size OFFSET p_offset)
            SELECT jsonb_build_object('companyId',core.current_company(),'currency','AUD','basis','POSTING_DATE','snapshotAt',statement_timestamp(),'asOf',p_date,'side',p_side,'partyId',p_party,'page',(p_offset/p_size+1),'pageSize',p_size,'totalCount',t.count,
              'totals',jsonb_build_object('current',t.current::text,'days1To30',t.d30::text,'days31To60',t.d60::text,'days61To90',t.d90::text,'daysOver90',t.older::text,'outstanding',t.gross::text,'availableCredit',t.credits::text,'netBalance',t.net::text,'controlBalance',c.balance::text,'difference',(t.net-c.balance)::text),
              'status',CASE WHEN t.net=c.balance THEN 'RECONCILED' ELSE 'UNRECONCILED' END,
              'items',coalesce((SELECT jsonb_agg(jsonb_build_object('documentId',id,'number',number,'partyId',party_id,'counterpartyId',counterparty_id,'partyName',legal_name,'invoiceDate',invoice_date,'dueOn',due_on,'daysOverdue',greatest(p_date-due_on,0),'bucket',CASE WHEN due_on>=p_date THEN 'CURRENT' WHEN p_date-due_on<=30 THEN '1_30' WHEN p_date-due_on<=60 THEN '31_60' WHEN p_date-due_on<=90 THEN '61_90' ELSE 'OVER_90' END,'outstanding',outstanding::text,'availableCredit',credit::text,'netBalance',net::text)ORDER BY due_on,id) FROM paged),'[]'::jsonb)) AS result FROM totals t CROSS JOIN control c
            
$$;

CREATE FUNCTION workbench.tasks(p_customer uuid,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN
 IF NOT crm.mobile_permission('crm.tasks.read')THEN RETURN workbench.unavailable();END IF;
 RETURN workbench.available((WITH visible AS MATERIALIZED(SELECT t.* FROM crm.tasks t WHERE t.company_id=core.current_company()AND t.state<>'DELETED'AND crm.task_visible_to(t.id,core.current_actor())AND(p_customer IS NULL OR t.customer_id=p_customer)),totals AS(SELECT count(*)total,count(*)FILTER(WHERE state IN('OPEN','IN_PROGRESS'))open,count(*)FILTER(WHERE state IN('OPEN','IN_PROGRESS')AND due_at<statement_timestamp())overdue,count(*)FILTER(WHERE state IN('OPEN','IN_PROGRESS')AND due_at>=statement_timestamp()AND due_at<statement_timestamp()+interval '7 days')due_soon FROM visible)
 SELECT jsonb_build_object('basis','CURRENT_AUTHORIZED_TASKS','totalCount',total,'open',open,'overdue',overdue,'dueNext7Days',due_soon,'upNext',(SELECT coalesce(jsonb_agg(crm.task_json(t.id)ORDER BY t.due_at NULLS LAST,t.id),'[]')FROM(SELECT*FROM visible WHERE state IN('OPEN','IN_PROGRESS')ORDER BY due_at NULLS LAST,id LIMIT p_size OFFSET p_offset)t),'items',(SELECT coalesce(jsonb_agg(crm.task_json(t.id)ORDER BY t.due_at NULLS LAST,t.id),'[]')FROM(SELECT*FROM visible ORDER BY due_at NULLS LAST,id LIMIT p_size OFFSET p_offset)t))FROM totals));END$$;
CREATE FUNCTION workbench.collaboration(p_customer uuid,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN
 IF NOT crm.mobile_permission('crm.collaboration.read')THEN RETURN workbench.unavailable();END IF;
 RETURN workbench.available((WITH visible AS MATERIALIZED(SELECT o.*FROM crm.collaboration_objects o WHERE o.company_id=core.current_company()AND o.state<>'DELETED'AND crm.collab_visible(o.id)AND(p_customer IS NULL OR o.customer_id=p_customer))
 SELECT jsonb_build_object('basis','CURRENT_AUTHORIZED_OBJECTS','totalCount',count(*),'notes',count(*)FILTER(WHERE kind='NOTE'),'displayedBoards',count(*)FILTER(WHERE kind='BOARD'AND state='DISPLAYED'),'openVisits',count(*)FILTER(WHERE kind='VISIT'AND state='OPEN'),'items',(SELECT coalesce(jsonb_agg(crm.collab_json(o.id)ORDER BY o.updated_at DESC,o.id),'[]')FROM(SELECT*FROM visible ORDER BY updated_at DESC,id LIMIT p_size OFFSET p_offset)o))FROM visible));END$$;
CREATE FUNCTION workbench.documents(p_customer uuid,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$DECLARE quotes jsonb;orders jsonb;BEGIN
 IF crm.mobile_permission('sales.quotes.read')THEN
 WITH visible AS MATERIALIZED(SELECT q.id,q.customer_id,d.number,q.status AS state,d.state AS document_state,d.business_date,q.net,q.tax,q.gross,d.version FROM sales.quotes q JOIN platform.documents d ON d.company_id=q.company_id AND d.id=q.id WHERE q.company_id=core.current_company()AND platform.document_visible(d.id) AND crm.mobile_customer_visible(q.customer_id)AND(p_customer IS NULL OR q.customer_id=p_customer))
 SELECT workbench.available(jsonb_build_object('totalCount',count(*),'submitted',count(*)FILTER(WHERE state='SUBMITTED'),'items',(SELECT coalesce(jsonb_agg(to_jsonb(x)ORDER BY x.business_date DESC,x.id),'[]')FROM(SELECT*FROM visible ORDER BY business_date DESC,id LIMIT p_size OFFSET p_offset)x)))INTO quotes FROM visible;ELSE quotes:=workbench.unavailable();END IF;
 IF crm.mobile_permission('sales.orders.read')THEN
 WITH visible AS MATERIALIZED(SELECT o.id,o.customer_id,d.number,d.state,d.business_date,o.net,o.tax,o.gross,d.version FROM sales.orders o JOIN platform.documents d ON d.company_id=o.company_id AND d.id=o.id WHERE o.company_id=core.current_company()AND platform.document_visible(d.id) AND crm.mobile_customer_visible(o.customer_id)AND(p_customer IS NULL OR o.customer_id=p_customer))
 SELECT workbench.available(jsonb_build_object('totalCount',count(*),'confirmed',count(*)FILTER(WHERE state='CONFIRMED'),'items',(SELECT coalesce(jsonb_agg(to_jsonb(x)ORDER BY x.business_date DESC,x.id),'[]')FROM(SELECT*FROM visible ORDER BY business_date DESC,id LIMIT p_size OFFSET p_offset)x)))INTO orders FROM visible;ELSE orders:=workbench.unavailable();END IF;
 RETURN jsonb_build_object('basis','CURRENT_VISIBLE_DOCUMENTS','quotes',quotes,'orders',orders);END$$;
CREATE FUNCTION workbench.drafts(p_customer uuid,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN
 IF NOT crm.mobile_permission('crm.drafts.read')THEN RETURN workbench.unavailable();END IF;
 RETURN workbench.available((WITH visible AS MATERIALIZED(SELECT d.*FROM crm.mobile_drafts d WHERE d.company_id=core.current_company()AND d.state<>'DELETED'AND(d.owner_id=core.current_actor()OR crm.mobile_reviewer())AND crm.mobile_customer_visible(d.customer_id)AND(p_customer IS NULL OR d.customer_id=p_customer OR(d.kind='CUSTOMER'AND d.formal_id=p_customer)))
 SELECT jsonb_build_object('totalCount',count(*),'submitted',count(*)FILTER(WHERE state='SUBMITTED'),'items',(SELECT coalesce(jsonb_agg(crm.draft_json(d.id)ORDER BY d.updated_at DESC,d.id),'[]')FROM(SELECT*FROM visible ORDER BY updated_at DESC,id LIMIT p_size OFFSET p_offset)d))FROM visible));END$$;
CREATE FUNCTION workbench.messages(p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN IF NOT crm.mobile_permission('crm.notifications.read')THEN RETURN workbench.unavailable();END IF;RETURN workbench.available(crm.message_list(true,p_size,p_offset));END$$;
CREATE FUNCTION workbench.incentives(p_customer uuid DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$DECLARE body jsonb;BEGIN IF NOT crm.mobile_permission('incentives.self.read')THEN RETURN workbench.unavailable();END IF;body:=incentives.personal();IF p_customer IS NOT NULL THEN SELECT coalesce(jsonb_agg(e ORDER BY e->>'programId'),'[]')INTO body FROM jsonb_array_elements(body)e JOIN incentives.programs p ON p.company_id=core.current_company()AND p.id=(e->>'programId')::uuid AND p.kind='REBATE'AND p.customer_id=p_customer;END IF;RETURN workbench.available(body);END$$;
CREATE FUNCTION workbench.sales(p_from date,p_to date,p_customer uuid,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$DECLARE report jsonb;BEGIN
 IF NOT crm.mobile_permission('reports.sales.read')OR NOT crm.mobile_permission('customers.read')THEN RETURN workbench.unavailable();END IF;
 report:=sales.analytics_report(jsonb_build_object('from',p_from,'to',p_to,'bucket','MONTH','customerId',p_customer));RETURN workbench.available(report-'sourceFacts'-'rows'-'pendingReturns'||jsonb_build_object('rowCount',jsonb_array_length(report->'rows'),'pendingReturnCount',jsonb_array_length(report->'pendingReturns'),'rows',(SELECT coalesce(jsonb_agg(e ORDER BY n),'[]')FROM jsonb_array_elements(report->'rows')WITH ORDINALITY x(e,n)WHERE n>p_offset AND n<=p_offset+p_size),'pendingReturns',(SELECT coalesce(jsonb_agg(e ORDER BY n),'[]')FROM jsonb_array_elements(report->'pendingReturns')WITH ORDINALITY x(e,n)WHERE n>p_offset AND n<=p_offset+p_size)));END$$;
CREATE FUNCTION workbench.bank_hub(p_asof date,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN
 PERFORM crm.require_mobile('accounting.banks.read');PERFORM crm.require_mobile('accounting.ledger.read');PERFORM crm.require_mobile('accounting.bank_statements.read');
 RETURN(WITH accounts AS MATERIALIZED(SELECT b.id,b.name,b.kind,b.active,a.code,b.account_number FROM accounting.bank_accounts b JOIN accounting.accounts a ON a.company_id=b.company_id AND a.id=b.id WHERE b.company_id=core.current_company()),paged AS(SELECT*FROM accounts ORDER BY code,id LIMIT p_size OFFSET p_offset)
 SELECT jsonb_build_object('asOf',p_asof,'balanceBasis','POSTING_DATE_INCLUSIVE','matchingBasis','CURRENT_STATUS_FOR_TRANSACTIONS_THROUGH_ASOF','feeds',jsonb_build_object('status','NOT_CONFIGURED','source','MANUAL_IMPORT','liveConnection',false),'totalCount',(SELECT count(*)FROM accounts),'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'name',b.name,'code',b.code,'kind',b.kind,'active',b.active,'accountNumberMasked',CASE WHEN b.account_number IS NOT NULL THEN'****'||right(b.account_number,4)END,
 'bookBalance',(SELECT coalesce(sum(l.debit-l.credit),0)::text FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE l.company_id=core.current_company()AND l.account_id=b.id AND j.posting_date<=p_asof),
 'latestStatement',(SELECT jsonb_build_object('id',s.id,'to',s.to_date,'closingBalance',s.closing_balance::text,'importedAt',s.created_at,'state',c.state)FROM accounting.bank_statements s JOIN accounting.bank_statement_controls c ON c.company_id=s.company_id AND c.id=s.id WHERE s.company_id=core.current_company()AND s.bank_account_id=b.id AND c.state<>'VOID'AND s.to_date<=p_asof ORDER BY s.to_date DESC,s.created_at DESC,s.id LIMIT 1),
 'latestReconciliation',(SELECT jsonb_build_object('id',r.id,'to',r.to_date,'statementClosing',r.closing_balance::text,'bookClosing',r.book_closing::text)FROM accounting.active_bank_reconciliations r WHERE r.company_id=core.current_company()AND r.bank_account_id=b.id AND r.to_date<=p_asof ORDER BY r.to_date DESC,r.created_at DESC,r.id LIMIT 1),
 'unmatchedLines',(SELECT count(*)FROM accounting.bank_statement_lines l JOIN accounting.bank_statement_controls c ON c.company_id=l.company_id AND c.id=l.statement_id WHERE l.company_id=core.current_company()AND l.bank_account_id=b.id AND c.state<>'VOID'AND l.transaction_date<=p_asof AND abs(l.amount)>coalesce((SELECT sum(a.amount)FROM accounting.active_bank_matches m JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.id WHERE m.company_id=l.company_id AND m.statement_line_id=l.id),0)),
 'rules',CASE WHEN crm.mobile_permission('accounting.bank_rules.read')THEN workbench.available((SELECT jsonb_build_object('enabled',count(*)FILTER(WHERE enabled),'disabled',count(*)FILTER(WHERE NOT enabled))FROM accounting.bank_rules r WHERE r.company_id=core.current_company()AND(r.bank_account_id IS NULL OR r.bank_account_id=b.id)))ELSE workbench.unavailable()END)ORDER BY b.code,b.id),'[]')FROM paged b)));END$$;
CREATE FUNCTION workbench.warehouse_visible(p_id uuid)RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT crm.mobile_permission('inventory.read')AND EXISTS(SELECT 1 FROM catalog.warehouses w WHERE w.company_id=core.current_company()AND w.id=p_id AND(crm.mobile_permission('warehouses.all')OR EXISTS(SELECT 1 FROM identity.warehouse_scopes s JOIN identity.memberships m ON m.company_id=s.company_id AND m.id=s.membership_id AND m.active WHERE s.company_id=w.company_id AND s.warehouse_id=w.id AND m.user_id=core.current_actor())))$$;
CREATE FUNCTION workbench.warehouse(p_warehouse uuid,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$BEGIN
 PERFORM crm.require_mobile('inventory.read');IF p_warehouse IS NOT NULL AND NOT workbench.warehouse_visible(p_warehouse)THEN RAISE EXCEPTION 'Warehouse unavailable' USING ERRCODE='HT404';END IF;
 RETURN(WITH visible AS MATERIALIZED(SELECT w.id,w.code,w.name,w.active FROM catalog.warehouses w WHERE w.company_id=core.current_company()AND workbench.warehouse_visible(w.id)AND(p_warehouse IS NULL OR w.id=p_warehouse)),paged AS(SELECT*FROM visible ORDER BY code,id LIMIT p_size OFFSET p_offset)
 SELECT jsonb_build_object('basis','CURRENT_QUANTITIES_NO_COSTS','totalCount',(SELECT count(*)FROM visible),'items',(SELECT coalesce(jsonb_agg(to_jsonb(w)||jsonb_build_object('stockSkuCount',(SELECT count(*)FROM inventory.stock_balances s WHERE s.company_id=core.current_company()AND s.warehouse_id=w.id),'pendingPicks',(SELECT count(*)FROM inventory.picks p JOIN sales.orders o ON o.company_id=p.company_id AND o.id=p.order_id JOIN platform.documents d ON d.company_id=p.company_id AND d.id=p.id WHERE p.company_id=core.current_company()AND o.warehouse_id=w.id AND p.state='PICKED'AND platform.document_visible(d.id)),
 'quantitiesByBaseUnit',(SELECT coalesce(jsonb_agg(to_jsonb(x)ORDER BY x.base_uom_id),'[]')FROM(SELECT p.base_uom_id,u.code AS unit,sum(s.on_hand)::text AS on_hand,sum(s.reserved)::text AS reserved,sum(s.on_hand-s.reserved)::text AS available FROM inventory.stock_balances s JOIN catalog.products p ON p.company_id=s.company_id AND p.id=s.product_id JOIN catalog.uoms u ON u.company_id=p.company_id AND u.id=p.base_uom_id WHERE s.company_id=core.current_company()AND s.warehouse_id=w.id GROUP BY p.base_uom_id,u.code)x))ORDER BY w.code,w.id),'[]')FROM paged w)));END$$;
CREATE FUNCTION workbench.query(p_kind text,f jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
DECLARE today date;first_date date;last_date date;asof_date date;sz int;pg int;off int;customer uuid;warehouse uuid;body jsonb;company core.companies;party uuid;BEGIN
 IF p_kind IS NULL OR p_kind NOT IN('FINANCE','SALES','OFFICE','CUSTOMER','BANKS','WAREHOUSE')THEN RAISE EXCEPTION 'Unknown workbench' USING ERRCODE='HR422';END IF;
 PERFORM crm.require_mobile(CASE p_kind WHEN'FINANCE'THEN'workbench.finance.read'WHEN'SALES'THEN'workbench.sales.read'WHEN'OFFICE'THEN'workbench.office.read'WHEN'CUSTOMER'THEN'workbench.customers.read'WHEN'BANKS'THEN'workbench.banks.read'ELSE'workbench.warehouse.read'END);
 SELECT*INTO company FROM core.companies WHERE id=core.current_company();today:=(statement_timestamp()AT TIME ZONE company.timezone)::date;
 IF jsonb_typeof(f)IS DISTINCT FROM'object'OR EXISTS(SELECT 1 FROM jsonb_object_keys(f)k WHERE k NOT IN('from','to','asOf','customerId','warehouseId','page','pageSize'))THEN RAISE EXCEPTION 'Invalid dashboard filter' USING ERRCODE='HR422';END IF;
 first_date:=coalesce((f->>'from')::date,date_trunc('month',today)::date);last_date:=coalesce((f->>'to')::date,today+1);asof_date:=coalesce((f->>'asOf')::date,last_date-1);sz:=coalesce((f->>'pageSize')::int,20);pg:=coalesce((f->>'page')::int,1);customer:=(f->>'customerId')::uuid;warehouse:=(f->>'warehouseId')::uuid;
 IF first_date<'0003-01-01'OR last_date<=first_date OR last_date-first_date>366 OR last_date>today+1 OR asof_date<'0003-01-01'OR asof_date>today OR sz NOT BETWEEN 1 AND 100 OR pg NOT BETWEEN 1 AND 1000000 OR customer='00000000-0000-0000-0000-000000000000'OR warehouse='00000000-0000-0000-0000-000000000000'OR(customer IS NOT NULL AND p_kind NOT IN('CUSTOMER','SALES','OFFICE'))OR(warehouse IS NOT NULL AND p_kind<>'WAREHOUSE')OR(f->>'asOf'IS NOT NULL AND p_kind<>'BANKS')THEN RAISE EXCEPTION 'Use valid scope, 1..366 days through today, and bounded pages' USING ERRCODE='HR422';END IF;off:=(pg-1)*sz;
 IF customer IS NOT NULL AND NOT crm.mobile_customer_visible(customer)THEN RAISE EXCEPTION 'Customer unavailable' USING ERRCODE='HT404';END IF;
 IF p_kind='FINANCE'THEN
 PERFORM workbench.require_finance();body:=jsonb_build_object('profitLoss',workbench.profit_loss(first_date,last_date)-'items','financialPosition',workbench.balance_sheet(asof_date)-'items','receivables',workbench.aging('AR',asof_date,NULL,sz,off),'payables',workbench.aging('AP',asof_date,NULL,sz,off),'tasks',workbench.tasks(NULL,sz,off),'messages',workbench.messages(sz,off));
 body:=body||jsonb_build_object('incomeExpenseChart',(WITH periods AS(SELECT generate_series(date_trunc('month',first_date)::date,date_trunc('month',last_date-1)::date,interval '1 month')::date bucket),amounts AS(SELECT date_trunc('month',j.posting_date)::date bucket,sum(l.credit-l.debit)FILTER(WHERE a.kind='REVENUE')revenue,sum(l.debit-l.credit)FILTER(WHERE a.kind='EXPENSE')expenses FROM accounting.journal_lines l JOIN accounting.business_journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=core.current_company()AND j.posting_date>=first_date AND j.posting_date<last_date AND a.kind IN('REVENUE','EXPENSE')GROUP BY 1)SELECT coalesce(jsonb_agg(jsonb_build_object('month',p.bucket,'revenue',coalesce(a.revenue,0)::text,'expenses',coalesce(a.expenses,0)::text,'netProfit',(coalesce(a.revenue,0)-coalesce(a.expenses,0))::text)ORDER BY p.bucket),'[]')FROM periods p LEFT JOIN amounts a USING(bucket)));
 ELSIF p_kind IN('SALES','OFFICE')THEN
 PERFORM crm.require_mobile('customers.read');IF p_kind='OFFICE'THEN PERFORM crm.require_mobile('customers.all');PERFORM crm.require_mobile('crm.collaboration.manage');END IF;
 body:=jsonb_build_object('customerCount',(SELECT count(*)FROM crm.customers c WHERE c.company_id=core.current_company()AND crm.mobile_customer_visible(c.id)AND(customer IS NULL OR c.id=customer)),'customers',(WITH visible AS MATERIALIZED(SELECT c.id,c.code,p.legal_name AS name,c.status FROM crm.customers c JOIN crm.parties p ON p.company_id=c.company_id AND p.id=c.party_id WHERE c.company_id=core.current_company()AND crm.mobile_customer_visible(c.id)AND(customer IS NULL OR c.id=customer))SELECT jsonb_build_object('totalCount',count(*),'items',(SELECT coalesce(jsonb_agg(to_jsonb(x)ORDER BY x.code,x.id),'[]')FROM(SELECT*FROM visible ORDER BY code,id LIMIT sz OFFSET off)x))FROM visible),'documents',workbench.documents(customer,sz,off),'tasks',workbench.tasks(customer,sz,off),'collaboration',workbench.collaboration(customer,sz,off),'drafts',workbench.drafts(customer,sz,off),'messages',workbench.messages(sz,off),'sales',workbench.sales(first_date,last_date,customer,sz,off),'incentives',workbench.incentives(customer));
 ELSIF p_kind='CUSTOMER'THEN
 PERFORM crm.require_mobile('customers.read');IF customer IS NULL THEN RAISE EXCEPTION 'Customer ID required' USING ERRCODE='HR422';END IF;SELECT party_id INTO party FROM crm.customers WHERE company_id=core.current_company()AND id=customer;
 body:=jsonb_build_object('customer',(SELECT jsonb_build_object('id',c.id,'code',c.code,'name',p.legal_name,'status',c.status)FROM crm.customers c JOIN crm.parties p ON p.company_id=c.company_id AND p.id=c.party_id WHERE c.company_id=core.current_company()AND c.id=customer),
 'branches',jsonb_build_object('totalCount',(SELECT count(*)FROM crm.customer_branches WHERE company_id=core.current_company()AND customer_id=customer),'items',(SELECT coalesce(jsonb_agg(to_jsonb(b)ORDER BY b.id),'[]')FROM(SELECT id,code,name,address_line1,suburb,state,postcode,active FROM crm.customer_branches WHERE company_id=core.current_company()AND customer_id=customer ORDER BY id LIMIT sz OFFSET off)b)),
 'contacts',jsonb_build_object('totalCount',(SELECT count(*)FROM crm.contacts WHERE company_id=core.current_company()AND party_id=party),'items',(SELECT coalesce(jsonb_agg(to_jsonb(c)ORDER BY c.id),'[]')FROM(SELECT id,name,email,phone,job_title,active FROM crm.contacts WHERE company_id=core.current_company()AND party_id=party ORDER BY id LIMIT sz OFFSET off)c)),
 'documents',workbench.documents(customer,sz,off),'tasks',workbench.tasks(customer,sz,off),'collaboration',workbench.collaboration(customer,sz,off),'drafts',workbench.drafts(customer,sz,off),'sales',workbench.sales(first_date,last_date,customer,sz,off),'rebates',workbench.incentives(customer),'receivables',CASE WHEN crm.mobile_permission('accounting.reports.read')AND crm.mobile_permission('accounting.ledger.read')THEN workbench.available(workbench.aging('AR',asof_date,party,sz,off))ELSE workbench.unavailable()END);
 ELSIF p_kind='BANKS'THEN body:=workbench.bank_hub(asof_date,sz,off);
 ELSE body:=workbench.warehouse(warehouse,sz,off);END IF;
 RETURN jsonb_build_object('schemaVersion',1,'kind',p_kind,'companyId',company.id,'timezone',company.timezone,'currency','AUD','snapshotAt',statement_timestamp(),'mvccSnapshot',pg_current_snapshot()::text,'readOnly',true,'period',CASE WHEN p_kind IN('WAREHOUSE','BANKS')THEN NULL ELSE jsonb_build_object('from',first_date,'to',last_date,'asOf',asof_date)END,'operationalBasis','CURRENT_COMMITTED_AND_CURRENT_AUTHORIZATION','page',pg,'pageSize',sz,'data',body);
END$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA workbench FROM PUBLIC;
REVOKE ALL ON FUNCTION identity.seed_workbench_roles(uuid)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION workbench.query(text,jsonb)TO htt_app;
